corrected={67:'The full topic supplies the missing continuation on scans52,54; the Hua register remains a lead.',95:'Completion continuation on51,53,55 adds tensor-completion and flatness; no conclusion about absent cote44.',98:'Reclassified as the earlier run’s literature idea; not an implication asserted by these pages.',100:'Reclassified as external-project planning; its quoted source is not on this page.',101:'Reclassified as external-project planning; cote44 endpoints are not supplied.',102:'Expanded titles through97 and replaced obsolete53 metadata by current catalogue96.',103:'Expanded n°276 pagination with scans51,53,55; original counts were selection-bound.'}
entries=[]
for it in items:
    for j,src in enumerate(it['sources']):
        n=int(src.split('#')[1])
        verdict='corrected' if n in corrected else ('kept' if j==0 else 'merged into '+it['id'])
        reason=corrected.get(n,it['check_reason'])
        entries.append(dict(entry_id=src,item_id=it['id'],verdict=verdict,reason=reason))
assert len(entries)==103 and {int(x['entry_id'].split('#')[1]) for x in entries}==set(range(1,104))
(P/'items.json').write_text(json.dumps(items,ensure_ascii=False,indent=2))
with (P/'entries.tsv').open('w') as f:
    w=csv.DictWriter(f,['entry_id','item_id','verdict','reason'],delimiter='\t');w.writeheader();w.writerows(sorted(entries,key=lambda x:int(x['entry_id'].split('#')[1])))
with (P/'progress.log').open('a') as f:f.write(datetime.datetime.now(datetime.timezone.utc).isoformat()+'\tSTAGE1\tRead103 entries and all four cote62 transcriptions; serialized97 distinct items.\n')
print(f'{len(items)} items; {len(entries)} source verdicts; all103 covered.')
